INSERT INTO `penyakit` VALUES (15,'P01','Karies Media','karies sudah mengenai dentins, tetapi belum melebihi setengah dentins','Perawatans tumpatan komposit/GIC dengan atau tanpa liners'),(16,'P02','Karies Profunda','Karies yang sudah mengenai lebih dari setengah dentin dan kadang – kadang sudah mengenai pulpa','Perawatan dapat berupa tumpatan dengan disertai perawatan pulp capping'),(17,'P03','Pulpitis Reversibel','radang pulpa yang ringan, jika penyebab radang dihilangkan maka pulpa akan kembali normal','Perawatan dapat berupa perawatan saluran akar yakni pulpektomi'),(18,'P04','Pulpitis Ireversibel Akut','Suatu keadaan inflamasi pulpa yang persisten, dapat simtomatik','Perawatan dapat berupa perawatan saluran akar yakni pulpektomi'),(19,'P05','Pulpitis Ireversibel Kronis','radang pada pulpa yang disebabkan oleh inflamasi jaringan keras, sehingga sistem pertahanan jaringan pulpa tidak dapat memperbaiki dan pulpa tidak dapat pulih kembali','Perawatan dapat berupa perawatan saluran akar yakni pulpektomi'),(20,'P06','Nekorosis Pulpa','keadaan pulpa yang sudah mati, aliran pembuluh darah sudah tidak ada, dan syaraf pulpa sudah tidak berfungsi kembali','Perawatan berupa perawatan saluran akar yakni pulpektomi.');
/*!40000 ALTER TABLE `penyakit` ENABLE KEYS */;
